do $$ declare expr text; begin select pg_get_expr(conbin,conrelid) into strict expr from pg_constraint where conrelid='public.job_board_visitor_sessions'::regclass and conname='job_board_visitor_sessions_actor_email_check'; alter table public.job_board_visitor_sessions drop constraint job_board_visitor_sessions_actor_email_check; execute 'alter table public.job_board_visitor_sessions add constraint job_board_visitor_sessions_actor_email_check check ((identity_type = ''visitor'' and actor_email = '''') or ('||expr||'))'; end $$;
